package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string          // PIC X(5) @0 len=5
	OrStat  string          // PIC X(1) @5 len=1
	OrQty   int64           // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

var WsEofFlag string // PIC X len=1 = "N"
var WsTotal decimal.Decimal
var WsGrand decimal.Decimal
var WsNewCount int64
var WsShipCount int64
var WsCancelCount int64
var WsInvalid int64
var WsBadQty int64
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderRec OrderRec

var orderLines []string
var orderIdx int
var inputDone bool

func main() {
	WsEofFlag = "N"
	WsTotal = decimal.New(0, 0)
	WsGrand = decimal.New(0, 0)
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0
	inputDone = false

	// OPEN INPUT ORDER-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found treat as empty – still need summary
		orderLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// increase buffer for long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			// strip single \r if present (LINE SEQUENTIAL may have CRLF)
			if strings.HasSuffix(line, "\r") {
				line = strings.TrimSuffix(line, "\r")
			}
			orderLines = append(orderLines, line)
		}
		f.Close()
	}

	// PERFORM READ-PARA
	readPara()
	// PERFORM PROCESS-PARA UNTIL INPUT-DONE
	for !inputDone {
		processPara()
	}
	// CLOSE ORDER-FILE (no action needed)
	// PERFORM SUMMARY-PARA
	summaryPara()
}

// READ-PARA.
func readPara() {
	if orderIdx >= len(orderLines) {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	raw := orderLines[orderIdx]
	orderIdx++
	// pad with spaces on right to record length 15
	if len(raw) < 15 {
		raw = raw + strings.Repeat(" ", 15-len(raw))
	} else if len(raw) > 15 {
		raw = raw[:15]
	}
	// parse fields
	orderRec.OrId = raw[0:5]
	orderRec.OrStat = raw[5:6]
	qtyStr := raw[6:9]
	qtyStr = strings.TrimSpace(qtyStr)
	var q int64
	if qtyStr != "" {
		// digits only
		var v int64
		fmt.Sscanf(qtyStr, "%d", &v)
		q = v
	} else {
		q = 0
	}
	orderRec.OrQty = q
	priceStr := raw[9:15]
	priceStr = strings.TrimSpace(priceStr)
	if priceStr == "" {
		orderRec.OrPrice = decimal.New(0, -2)
	} else {
		// price string contains digits only, implied V99
		var iv int64
		fmt.Sscanf(priceStr, "%d", &iv)
		orderRec.OrPrice = decimal.New(iv, -2)
	}
}

// PROCESS-PARA.
func processPara() {
	WsTotal = decimal.New(0, 0)

	// EVALUATE TRUE order matters
	if orderRec.OrQty == 0 {
		WsBadQty = truncCount(WsBadQty + 1)
		fmt.Println(orderRec.OrId + " BAD QTY")
	} else if orderRec.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE
		qd := decimal.New(orderRec.OrQty, 0)
		comp := qd.Mul(orderRec.OrPrice)
		// truncation to scale 2 (target 9(8)V99 scale 2)
		comp = comp.Truncate(2)
		WsTotal = storeDecimal(comp, 8, 2)
		WsNewCount = truncCount(WsNewCount + 1)
		showPara()
	} else if orderRec.OrStat == "S" {
		qd := decimal.New(orderRec.OrQty, 0)
		comp := qd.Mul(orderRec.OrPrice).Mul(decimal.New(105, -2)) // *1.05
		comp = comp.Round(2) // ROUNDED half away from zero
		WsTotal = storeDecimal(comp, 8, 2)
		WsShipCount = truncCount(WsShipCount + 1)
		showPara()
	} else if orderRec.OrStat == "C" {
		WsCancelCount = truncCount(WsCancelCount + 1)
		showPara()
	} else {
		WsInvalid = truncCount(WsInvalid + 1)
		fmt.Println(orderRec.OrId + " BAD STATUS " + orderRec.OrStat)
	}
	// ADD WS-TOTAL TO WS-GRAND
	WsGrand = storeDecimal(WsGrand.Add(WsTotal), 10, 2)
	// PERFORM READ-PARA
	readPara()
}

// SHOW-PARA.
func showPara() {
	WsQtyEd = formatEdited(decimal.New(orderRec.OrQty, 0), "ZZ9")
	WsPriceEd = formatEdited(orderRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Println(orderRec.OrId + " " + orderRec.OrStat + " " + WsQtyEd + " " + WsPriceEd + " " + WsTotalEd)
}

// SUMMARY-PARA.
func summaryPara() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Println("NEW: " + fmtCount(WsNewCount) + " SHIPPED: " + fmtCount(WsShipCount) + " CANCELLED: " + fmtCount(WsCancelCount))
	fmt.Println("INVALID: " + fmtCount(WsInvalid) + " BAD QTY: " + fmtCount(WsBadQty))
	fmt.Println("GRAND TOTAL: " + WsGrandEd)
}

func fmtCount(v int64) string {
	// PIC 99 zero padded 2
	return fmt.Sprintf("%02d", v%100)
}
func truncCount(v int64) int64 {
	return v % 100
}

// storeDecimal truncates high-order integer digits to fit intDigits.
func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// v is already at desired scale (maybe need truncate)
	// keep only low-order intDigits digits
	if intDigits <= 0 {
		return v
	}
	// work with absolute for truncation logic then restore sign
	sign := v.Sign()
	av := v.Abs()
	// ensure scale exactly
	av = av.Truncate(scale)
	s := av.StringFixed(scale) // e.g. "1234.56" or "1234" if scale 0? for scale 0 StringFixed returns "1234"
	var intPartStr, fracPartStr string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", int(scale))
		}
		// remove sign if any
		if strings.HasPrefix(intPartStr, "-") {
			intPartStr = intPartStr[1:]
		}
		if intPartStr == "" {
			intPartStr = "0"
		}
		if len(intPartStr) > intDigits {
			intPartStr = intPartStr[len(intPartStr)-intDigits:]
		}
		// strip leading zeros for numeric value then rebuild? keep as is for decimal creation
		// Build decimal from string
		combined := intPartStr + "." + fracPartStr
		d, _ := decimal.NewFromString(combined)
		if sign < 0 {
			d = d.Neg()
		}
		return d
	}
	// scale 0
	s2 := av.StringFixed(0)
	if strings.HasPrefix(s2, "-") {
		s2 = s2[1:]
	}
	if len(s2) > intDigits {
		s2 = s2[len(s2)-intDigits:]
	}
	d, _ := decimal.NewFromString(s2)
	if sign < 0 {
		d = d.Neg()
	}
	return d
}

// formatEdited formats decimal v according to picture pic containing Z,9,',','.'
func formatEdited(v decimal.Decimal, pic string) string {
	av := v.Abs()
	// split pic
	var intPic, fracPic string
	if idx := strings.Index(pic, "."); idx >= 0 {
		intPic = pic[:idx]
		fracPic = pic[idx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == '9' {
			fracDigits++
		}
	}
	intDigitsNeeded := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigitsNeeded++
		}
	}
	// get integer and fractional strings at required scale
	var intPartStr, fracPartStr string
	if fracDigits > 0 {
		s := av.StringFixed(int32(fracDigits))
		parts := strings.SplitN(s, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", fracDigits)
		}
		if intPartStr == "" {
			intPartStr = "0"
		}
		// remove minus sign (abs)
		if strings.HasPrefix(intPartStr, "-") {
			intPartStr = intPartStr[1:]
		}
	} else {
		s := av.Truncate(0).StringFixed(0)
		intPartStr = s
		if strings.HasPrefix(intPartStr, "-") {
			intPartStr = intPartStr[1:]
		}
		if intPartStr == "" {
			intPartStr = "0"
		}
		fracPartStr = ""
	}
	// handle overflow: keep low-order digits
	if len(intPartStr) > intDigitsNeeded {
		intPartStr = intPartStr[len(intPartStr)-intDigitsNeeded:]
	} else if len(intPartStr) < intDigitsNeeded {
		intPartStr = strings.Repeat("0", intDigitsNeeded-len(intPartStr)) + intPartStr
	}
	// Build edited integer part
	// Map digits to pic positions
	digitIdx := 0
	suppress := true
	var editedInt strings.Builder
	for _, pc := range intPic {
		if pc == ',' {
			if suppress {
				editedInt.WriteRune(' ')
			} else {
				editedInt.WriteRune(',')
			}
		} else if pc == 'Z' || pc == '9' {
			d := intPartStr[digitIdx]
			digitIdx++
			if suppress {
				if pc == 'Z' && d == '0' {
					// check if this is to be suppressed: but if all remaining are also to be suppressed and no mandatory digit forces display, last 9 case will still display
					// For Z zero we suppress and stay in suppress mode
					editedInt.WriteRune(' ')
				} else {
					// either Z with non-zero, or 9 (mandatory)
					editedInt.WriteRune(rune(d))
					suppress = false
				}
			} else {
				editedInt.WriteRune(rune(d))
			}
		}
	}
	result := editedInt.String()
	if fracPic != "" {
		// ensure fracPartStr length
		if len(fracPartStr) < fracDigits {
			fracPartStr = fracPartStr + strings.Repeat("0", fracDigits-len(fracPartStr))
		} else if len(fracPartStr) > fracDigits {
			fracPartStr = fracPartStr[:fracDigits]
		}
		result = result + "." + fracPartStr
	}
	return result
}
